import{_ as a,a0 as o,w as p,s as d,I as n,x as i,a1 as e,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"在 LVM 上安装 Linux Mint | LCTT x X-CMD","titleTemplate":false,"description":"在 LVM 上安装 Linux Mint | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 LVM 上安装 Linux Mint | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 LVM 上安装 Linux Mint | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210813 Install Linux with LVM","title":"在 LVM 上安装 Linux Mint","tag":"202108","desc":""},"relativePath":"202108/20210813 Install Linux with LVM.md","filePath":"[post].md"}'),u={name:"202108/20210813 Install Linux with LVM.md"};function g(L,t,m,x,f,M){const s=o("Link");return p(),d("div",null,[t[28]||(t[28]=n("h1",{id:"在-lvm-上安装-linux-mint",tabindex:"-1"},[i("在 LVM 上安装 Linux Mint "),n("a",{class:"header-anchor",href:"#在-lvm-上安装-linux-mint","aria-label":"Permalink to “在 LVM 上安装 Linux Mint”"},"​")],-1)),t[29]||(t[29]=n("blockquote",null,[n("p",null,"一个关于让 Linux Mint 20.2 与逻辑卷管理器（LVM）一起工作的教程。")],-1)),t[30]||(t[30]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/21/104418yg111cba52caalc5.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=i("几周前，",-1)),e(s,{href:"https://linuxmint.com/"},{default:l(()=>[...t[0]||(t[0]=[i("Linux Mint",-1)])]),_:1}),t[2]||(t[2]=i(" 的人员发布了他们的开源操作系统的 20.2 版本。Live ISO 中内置的安装程序非常好，只需要点击几下就可以安装操作系统。如果你想定制你的分区，你甚至有一个内置的分区软件。",-1))]),n("p",null,[t[5]||(t[5]=i("安装程序重点关注在简单的安装上：定义你的分区并安装到这些分区。对于那些想要更灵活的设置的人来说，",-1)),n("ruby",null,[e(s,{href:"https://en.wikipedia.org/wiki/Logical_Volume_Manager_(Linux)"},{default:l(()=>[...t[3]||(t[3]=[i("逻辑卷管理器",-1)])]),_:1}),t[4]||(t[4]=n("rt",null,"logical volume manager",-1))]),t[6]||(t[6]=i("（LVM）是个不错的选择，你可以通过设置卷组（VG）并在其中定义你的逻辑卷（LV）。",-1))]),n("p",null,[t[8]||(t[8]=i("LVM 是一个硬盘管理系统，允许你在多个物理驱动器上创建存储空间。换句话说，你可以把几个小驱动器“拴”在一起，这样你的操作系统就会把它们当作一个驱动器。除此之外，它还有实时调整大小、文件系统快照和更多的优点。这篇文章并不是关于 LVM 的教程（网上已经有很多 ",-1)),e(s,{href:"https://opensource.com/business/16/9/linux-users-guide-lvm"},{default:l(()=>[...t[7]||(t[7]=[i("这方面不错的信息",-1)])]),_:1}),t[9]||(t[9]=i("了）。相反，我的目标是贴合这篇文章的主题，只关注让 Linux Mint 20.2 与 LVM 一起工作。",-1))]),t[31]||(t[31]=n("p",null,"作为一个桌面操作系统，其安装程序致力于简单化，在 LVM 上安装 Linux Mint 20.2 会略微复杂一些，但不会太复杂。如果你在安装程序中选择了 LVM，你会得到一个由 Linux Mint 开发者定义的设置，而且你在安装时无法控制各个卷。",-1)),t[32]||(t[32]=n("p",null,"然而，有一个解决方案：在临场 ISO 中，该方案只需要在终端中使用几个命令来设置 LVM，然后你可以继续使用常规安装程序来完成工作。",-1)),n("p",null,[t[11]||(t[11]=i("我安装了 Linux Mint 20.2 和 ",-1)),e(s,{href:"https://opensource.com/article/19/12/xfce-linux-desktop"},{default:l(()=>[...t[10]||(t[10]=[i("XFCE 桌面",-1)])]),_:1}),t[12]||(t[12]=i("，但其他 Linux Mint 桌面的过程也类似。",-1))]),t[33]||(t[33]=r(`<h3 id="分区驱动器" tabindex="-1">分区驱动器 <a class="header-anchor" href="#分区驱动器" aria-label="Permalink to “分区驱动器”">​</a></h3><p>在 Linux Mint 临场 ISO 中，你可以通过终端和 GUI 工具访问 Linux 命令行工具。如果你需要做任何分区工作，你可以使用命令行 <code>fdisk</code> 或 <code>parted</code> 命令，或者 GUI 应用 <code>gparted</code>。我想让这些操作简单到任何人都能遵循，所以我会在可能的情况下使用 GUI 工具，在必要时使用命令行工具。</p><p>首先，为安装创建几个分区。</p><p>使用 <code>gparted</code>（从菜单中启动），完成以下工作：</p><p>首先，创建一个 512MB 的分区，类型为 FAT32（这是用来确保系统可启动）。512MB 对大多数人来说是富余的，你可以用 256MB 甚至更少，但在今天的大容量磁盘中，即使分配 512MB 也不是什么大问题。</p><p><img src="https://opensource.com/sites/default/files/boot-part.png" alt="Creating a boot partition" title="Creating a boot partition"></p><p>接下来，在磁盘的其余部分创建一个 <code>lvm2 pv</code> 类型（LVM 2 物理卷）的分区（这是你的 LVM 的位置）。</p><p><img src="https://opensource.com/sites/default/files/part-layout.png" alt="Partition layout" title="Partition layout"></p><p>现在打开一个终端窗口，并将你的权限提升到 root：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -s</span></span>
<span class="line"><span># whoami</span></span>
<span class="line"><span>root</span></span></code></pre></div><p>接下来，你必须找到你之前创建的 LVM 成员（那个大分区）。使用下列命令之一：<code>lsblk -f</code> 或 <code>pvs</code> 或 <code>pvscan</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvs</span></span>
<span class="line"><span>PV      VG Fmt  [...]</span></span>
<span class="line"><span>/dev/sda2    lvm2 [...]</span></span></code></pre></div><p>在我的例子中，该分区位于 <code>/dev/sda2</code>，但你应该用你的输出中得到的内容来替换它。</p><p>现在你知道了你的分区有哪些设备，你可以在那里创建一个 LVM 卷组（VG）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgcreate vg /dev/sda2</span></span></code></pre></div><p>你可以使用 <code>vgs</code> 或 <code>vgscan</code> 看到你创建的卷组的细节。</p><p>创建你想在安装时使用的逻辑卷（LV）。为了简单，我分别创建了 <code>root</code> 根分区（<code>/</code>）和 <code>swap</code> 交换分区，但是你可以根据需要创建更多的分区（例如，为 <code>/home</code> 创建一个单独的分区）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvcreate -L 80G -n root vg</span></span>
<span class="line"><span># lvcreate -L 16G -n swap vg</span></span></code></pre></div><p>我的例子中的分区大小是任意的，是基于我可用的空间。使用对你的硬盘有意义的分区大小。</p><p>你可以用 <code>lvs</code> 或 <code>lvdisplay</code> 查看逻辑卷。</p><p>终端操作到这就结束了。</p><h3 id="安装-linux" tabindex="-1">安装 Linux <a class="header-anchor" href="#安装-linux" aria-label="Permalink to “安装 Linux”">​</a></h3><p>现在从桌面上的图标启动安装程序：</p><ul><li>进入 “Installation type”，选择 “Something else”。</li><li>编辑 512Mb 的分区并将其改为 <code>EFI</code>。</li><li>编辑根逻辑卷，将其改为 <code>ext4</code>（或一个你选择的文件系统）。选择将其挂载为根目录（<code>/</code>），并选择将其格式化。</li><li>编辑 <code>swap</code> 分区并将其设置为交换分区。</li><li>继续正常的安装过程。Linux Mint 安装程序会将文件放在正确的位置并为你创建挂载点。</li></ul><p>完成了。在你的 Linux Mint 安装中享受 LVM 的强大。</p><p>如果你需要调整分区大小或在系统上做任何高级工作，你会感谢选择 LVM。</p><hr>`,27)),n("p",null,[t[14]||(t[14]=i("via: ",-1)),e(s,{href:"https://opensource.com/article/21/8/install-linux-mint-lvm"},{default:l(()=>[...t[13]||(t[13]=[i("https://opensource.com/article/21/8/install-linux-mint-lvm",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=i("作者：",-1)),e(s,{href:"https://opensource.com/users/flyingrhino"},{default:l(()=>[...t[15]||(t[15]=[i("Kenneth Aaron",-1)])]),_:1}),t[20]||(t[20]=i(" 选题：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[16]||(t[16]=[i("lujun9972",-1)])]),_:1}),t[21]||(t[21]=i(" 译者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[17]||(t[17]=[i("geekpi",-1)])]),_:1}),t[22]||(t[22]=i(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[18]||(t[18]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[25]||(t[25]=i("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[23]||(t[23]=[i("LCTT",-1)])]),_:1}),t[26]||(t[26]=i(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:l(()=>[...t[24]||(t[24]=[i("Linux中国",-1)])]),_:1}),t[27]||(t[27]=i(" 荣誉推出",-1))])])}const v=a(u,[["render",g]]);export{h as __pageData,v as default};
